      with (l := [SCycL 4 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RC_1LB0RC_0RB1LD_1LA0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RC_1LB0RC_0RB1LD_1LA0LD
      with (l := [SCycL 4 0; SWin 3]).
    vm_compute; reflexivity.
Qed.

