(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_1RC0LD_1LD0RC_1LA1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB1RC_1RC0LD_1LD0RC_1LA1LA.
