  unfold Cc_1RB1RC_1RC0LD_1LD0RC_1LA1LA, cden, A0_1RB1RC_1RC0LD_1LD0RC_1LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1RC_1RC0LD_1LD0RC_1LA1LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Kp q0 ++ [S0]) [] j A1_1RB1RC_1RC0LD_1LD0RC_1LA1LA = Cc (Pos.succ p).
