Definition BE0_1RB1RC_1RC1LA_1LD1RB_0RB0LD : sconf := mkC StD (mkS [] [S0;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RC_1RC1LA_1LD1RB_0RB0LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SWinL 6; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1RC_1RC1LA_1LD1RB_0RB0LD : srun tm true true che_1RB1RC_1RC1LA_1LD1RB_0RB0LD BE0_1RB1RC_1RC1LA_1LD1RB_0RB0LD = Some (B1_1RB1RC_1RC1LA_1LD1RB_0RB0LD, 4, 12).
