(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RC_1RC1LA_1LD1RB_0RB0LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1RC_1RC1LA_1LD1RB_0RB0LD.
Proof.
