Lemma lapi_1RB1RC_1RC1LA_1LD1RB_0RB0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
