Lemma gen_1RB1RC_1RC1LA_1LD1RB_0RB0LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB1RC_1RC1LA_1LD1RB_0RB0LD) = lift (Cin (Pos.succ v)).
Proof.
