  unfold Cin_1RB1RC_1RC1LA_1LD1RB_0RB0LD, cden, AI1_1RB1RC_1RC1LA_1LD1RB_0RB0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
