(** ** The lap *)

Lemma lap_1RB1RD_0LB1LC_1RB0RA_1LB0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
