    apply (lap_of_run tm Cc true true cho_1RB1RD_0LB1LC_1RB0RA_1LB0RD B0_1RB1RD_0LB1LC_1RB0RA_1LB0RD B1_1RB1RD_0LB1LC_1RB0RA_1LB0RD 2 16 p j' [] []).
