    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_0LB1LC_1RB0RA_1LB0RD p j' E).
    + exact (geo_1RB1RD_0LB1LC_1RB0RA_1LB0RD p j' E).
    + lia.
