(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_0LB1LC_1RB0RA_1LB0RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_0LB1LC_1RB0RA_1LB0RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_0LB1LC_1RB0RA_1LB0RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_0LB1LC_1RB0RA_1LB0RD : forall t, ~ In t pins_1RB1RD_0LB1LC_1RB0RA_1LB0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1; SWinR 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1; SWinR 3] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1; SWinR 5] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LB1LC_1RB0RA_1LB0RD [SWin 1; SWinR 11] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB1RD_0LB1LC_1RB0RA_1LB0RD : NonHalt tmm_1RB1RD_0LB1LC_1RB0RA_1LB0RD /\ QHBoundTr 32779478 tmm_1RB1RD_0LB1LC_1RB0RA_1LB0RD /\ QuasiHaltsTr tmm_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
Proof.
  apply (lap_qh_stage tmm_1RB1RD_0LB1LC_1RB0RA_1LB0RD pins_1RB1RD_0LB1LC_1RB0RA_1LB0RD Cc 1 15 32779478).
  - exact bootq_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
  - intros p _. apply lap_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
  - intros t Ht p _. apply fire_1RB1RD_0LB1LC_1RB0RA_1LB0RD. exact Ht.
  - exact wit_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
  - apply qcleb_QC_30. reflexivity.
Qed.

Theorem qhtr_1RB1RD_0LB1LC_1RB0RA_1LB0RD : NonHalt tm_1RB1RD_0LB1LC_1RB0RA_1LB0RD /\ QHBoundTr 32779478 tm_1RB1RD_0LB1LC_1RB0RA_1LB0RD /\ QuasiHaltsTr tm_1RB1RD_0LB1LC_1RB0RA_1LB0RD.
