(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RD_0LC1RB_1LD0RB_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j A0_1RB1RD_0LC1RB_1LD0RB_1RA1LC.
