  unfold Cc_1RB1RD_0LC1RB_1LD0RB_1RA1LC, cden, A0_1RB1RD_0LC1RB_1LD0RB_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RD_0LC1RB_1LD0RB_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0;S1;S0]) [] j A1_1RB1RD_0LC1RB_1LD0RB_1RA1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB1RD_0LC1RB_1LD0RB_1RA1LC, cden, A1_1RB1RD_0LC1RB_1LD0RB_1RA1LC; cbn [c_st c_l c_h c_r].
