Lemma geo_1RB1RD_0LC1RB_1LD0RB_1RA1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_0LC1RB_1LD0RB_1RA1LC) = lift (Cc (Pos.succ p)).
