  - destruct (lapi_1RB1RD_0LC1RB_1LD0RB_1RA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_0LC1RB_1LD0RB_1RA1LC B0_1RB1RD_0LC1RB_1LD0RB_1RA1LC B1_1RB1RD_0LC1RB_1LD0RB_1RA1LC 4 16 p j' [] []).
    + exact run_ovf_1RB1RD_0LC1RB_1LD0RB_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_0LC1RB_1LD0RB_1RA1LC p j' E).
    + exact (geo_1RB1RD_0LC1RB_1LD0RB_1RA1LC p j' E).
    + lia.
