(** ** Bootstrap *)

Lemma bootq_1RB1RD_0LC1RB_1LD0RB_1RA1LC : stepn tm_1RB1RD_0LC1RB_1LD0RB_1RA1LC 20 InitES = Some (lift (Cc 1)).
