Lemma geo_1RB1RD_0LC1RD_1RB1LC_1LA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_0LC1RD_1RB1LC_1LA0RB) = lift (Cc (Pos.succ p)).
