(** ** The lap *)

Lemma lap_1RB1RD_0LC1RD_1RB1LC_1LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_0LC1RD_1RB1LC_1LA0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RD_0LC1RD_1RB1LC_1LA0RB B0_1RB1RD_0LC1RD_1RB1LC_1LA0RB B1_1RB1RD_0LC1RD_1RB1LC_1LA0RB 4 13 p j' [] []).
    + exact run_ovf_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RD_0LC1RD_1RB1LC_1LA0RB p j' E).
    + exact (geo_1RB1RD_0LC1RD_1RB1LC_1LA0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RD_0LC1RD_1RB1LC_1LA0RB : stepn tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB 9 InitES = Some (lift (Cc 1)).
Proof.
