(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RD_0LC1RD_1RB1LC_1LA0RB : existsb (fun tg => cfires tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB c0 9 tg) pins_1RB1RD_0LC1RD_1RB1LC_1LA0RB = true.
