(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_0LC1RD_1RB1LC_1LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_0LC1RD_1RB1LC_1LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_0LC1RD_1RB1LC_1LA0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_0LC1RD_1RB1LC_1LA0RB : forall t, ~ In t pins_1RB1RD_0LC1RD_1RB1LC_1LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 2; SCycL 2 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RD_0LC1RD_1RB1LC_1LA0RB [SWinR 2; SCycL 2 0; SWin 5] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtr_1RB1RD_0LC1RD_1RB1LC_1LA0RB : NonHalt tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB /\ QHBoundTr 32779478 tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB /\ QuasiHaltsTr tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
Proof.
  apply (lap_qh_stage tm_1RB1RD_0LC1RD_1RB1LC_1LA0RB pins_1RB1RD_0LC1RD_1RB1LC_1LA0RB Cc 1 9 32779478).
  - exact bootq_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
  - intros p _. apply lap_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
  - intros t Ht p _. apply fire_1RB1RD_0LC1RD_1RB1LC_1LA0RB. exact Ht.
  - exact wit_1RB1RD_0LC1RD_1RB1LC_1LA0RB.
  - apply qcleb_QC_30. reflexivity.
Qed.

